entries[18454] = { ["name"] = "Handschuhe der Zauberbeherrschung", ["text"] = "Wirken in 15 sek.\nReagenzien:\nRunenstoffballen (10), Mondstoff (10), Geisterfarbstoff (10), Goldene Perle (6), Gewaltiger Smaragd (6), Verzaubertes Leder (8), Runenfaden (2)\nHandschuhe der Zauberbeherrschung\nWird beim Anlegen gebunden\nHände Stoff\n132 Rüstung\n+10 Intelligenz\n+8 Willenskraft\nErhöht Eure kritische Trefferwertung um + 28.\nHaltbarkeit 60 / 60\nKlassen: Priester , Magier , Hexenmeister\n57" }
entries[18455] = { ["name"] = "Bodenlose Tasche", ["text"] = "Wirken in 15 sek.\nReagenzien:\nRunenstoffballen (8), Mondstoff (12), Großer glänzender Splitter (2), Kernleder (2), Runenfaden (2)\nBodenlose Tasche\nWird beim Anlegen gebunden\n18 Platz Behälter" }
entries[18456] = { ["name"] = "Trachten des wahren Glaubens", ["text"] = "Wirken in 15 sek.\nReagenzien:\nRunenstoffballen (12), Mondstoff (10), Rechtschaffene Kugel (4), Goldene Perle (4), Geisterfarbstoff (10), Runenfaden (2)\nTrachten des wahren Glaubens\nWird beim Aufheben gebunden\nBrust Stoff\n211 Rüstung\n+14 Ausdauer\n+33 Intelligenz\n+16 Willenskraft\nHaltbarkeit 165 / 165\nKlassen: Priester\n57\nAnlegen: Verringert die Abklingzeit Eurer Fähigkeit 'Verblassen' um 2 Sek." }
entries[18457] = { ["name"] = "Robe des Erzmagiers", ["text"] = "Wirken in 15 sek.\nReagenzien:\nRunenstoffballen (12), Essenz des Feuers (10), Essenz der Luft (10), Essenz der Erde (10), Essenz des Wassers (10), Runenfaden (2)\nRobe des Erzmagiers\nWird beim Aufheben gebunden\nBrust Stoff\n211 Rüstung\n+18 Ausdauer\n+34 Intelligenz\nErhöht Eure kritische Trefferwertung um + 14.\nHaltbarkeit 165 / 165\n57\nBenutzen: Stellt 625 Mana wieder her. (5 Min Abklingzeit)" }
entries[18458] = { ["name"] = "Robe der Leere", ["text"] = "Wirken in 15 sek.\nReagenzien:\nRunenstoffballen (12), Dämonische Rune (20), Teufelsstoff (40), Essenz des Feuers (12), Essenz des Untodes (12), Runenfaden (2)\nRobe der Leere\nWird beim Aufheben gebunden\nBrust Stoff\n211 Rüstung\n+14 Ausdauer\n+39 Intelligenz\nHaltbarkeit 165 / 165\n57\nBenutzen: Heilt Euren Begleiter um 750 . (10 Min Abklingzeit)" }
entries[18476] = { ["name"] = "Untergebenen beschwören" }
entries[18498] = { ["name"] = "Zum Schweigen gebracht - Auf die Kehle zielen", ["text"] = "Unbegrenzte Reichweite\nSofort\nEure Fähigkeiten 'Zuschlagen' und 'Heldenhafter Wurf' bringen das Ziel zusätzlich 3 Sek. lang zum Schweigen. Funktioniert nicht gegen Spielercharaktere." }
entries[18499] = { ["name"] = "Berserkerwut", ["text"] = "Sofort 30 sek. Abklingzeit\nFuror ( Hotfix - Passivfähigkeit )\nVersetzt Euch in einen Wutzustand, der 10 Wut erzeugt und Euren körperlichen Schaden 6 Sek. lang um 10% erhöht.\n\nHebt außerdem Furcht- und Handlungsunfähigkeitseffekte auf und macht Euch während der Dauer von 'Berserkerwut' gegen diese Effekte immun.\n\nWaffen, Schutz\nVersetzt Euch in einen Wutzustand, der 10 Wut erzeugt und Euren körperlichen Schaden 6 Sek. lang um 10% erhöht.\n\nHebt außerdem Furcht- und Handlungsunfähigkeitseffekte auf und macht Euch während der Dauer von 'Berserkerwut' gegen diese Effekte immun." }
entries[18500] = { ["name"] = "Flügelstoß", ["text"] = "Wirken in 0.5 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 28275 bis 31725 Schaden zu und stößt sie zurück." }
entries[18501] = { ["name"] = "Wutanfall", ["text"] = "Sofort\nErhöht 5 Sek. lang den körperlichen Schaden, den der Zaubernde verursacht, und sein Angriffstempo." }
entries[18502] = { ["name"] = "Fluch von Hakkar", ["text"] = "200 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nEntzieht einem Feind alle 5 Sek. 100 Mana und überträgt sie 2 Min. lang auf den Zaubernden." }
entries[18503] = { ["name"] = "Verhexung", ["text"] = "20 Mana 20 Meter Reichweite\nSofort\nTransformiert einen Feind in ein Huhn, sodass er 5 Sek. lang weder angreifen noch Zauber wirken kann." }
entries[18540] = { ["name"] = "Verdammniswache beschwören", ["text"] = "25% von Grundmana 40 Meter Reichweite\nSofort 10 min Abklingzeit" }
entries[18542] = { ["name"] = "Feuerbrand", ["text"] = "(Procchance: 10%)" }
entries[18543] = { ["name"] = "Flammenpeitsche", ["text"] = "30 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 15 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[18545] = { ["name"] = "Skorpidgift", ["text"] = "10 Mana 5 - 30 Meter Reichweite\nBenötigt Distanzwaffe\nSticht einen Feind und verringert 20 Sek. lang Stärke und Beweglichkeit des Ziels um 1." }
entries[18546] = { ["name"] = "Overdrive", ["text"] = "Sofort\nMacht den Zaubernden bewegungsunfähig, erhöht aber 6 Sek. lang sein Angriffstempo um 100%." }
entries[18557] = { ["name"] = "Blutsauger", ["text"] = "75 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nEntzieht einem Gegner im Verlauf von 5 Sek. insgesamt 80 Gesundheit und überträgt sie auf den Zaubernden." }
entries[18559] = { ["name"] = "Dämonenhacke", ["text"] = "5 Meter Reichweite\nWirken in 5 sek.\nDämonenhacke zur Zerstörung des Dämonenkristalls." }
entries[18560] = { ["name"] = "Mondstoff", ["text"] = "Wirken in 15 sek.\nReagenzien:\nTeufelsstoff (2)\nDie Läuterung und Verwandlung von besudeltem Teufelsstoff in Mondstoff kann nur an einem Mondbrunnen durchgeführt werden. Zudem werden es die Wasser nur hin und wieder gestatten, auf diese Weise benutzt zu werden." }
entries[18561] = { ["name"] = "Schießen", ["text"] = "5 - 30 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt auf den Gegner und verursacht körperlichen Schaden." }
entries[18562] = { ["name"] = "Rasche Heilung", ["text"] = "8.5% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nHeilt ein verbündetes Ziel, auf dem ein Effekt von 'Verjüngung' oder 'Nachwachsen' wirkt, sofort um 13966 .\n\nHeilt außerdem die drei am schwersten verwundeten Verbündeten innerhalb von 10 Metern in der Nähe des ursprünglichen Ziels im Verlauf von 8 Sek. alle 2 Sek. um ( 13966 * 0.12)." }
