entries[19792] = { ["name"] = "Thoriumgewehr", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilrohr (2), Mithrilgehäuse (2), Thoriumapparat (2), Thoriumbarren (4), Tödliches Zielfernrohr\nThoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n70 - 131 Schaden Tempo 2.50\n(40.20 Schaden pro Sekunde)\n+ 53 Distanzangriffskraft\nHaltbarkeit 85 / 85\n47" }
entries[19793] = { ["name"] = "Lebensechte mechanische Kröte", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEssenz des Lebens , Thoriumapparat (4), Goldkraftkern , Unverwüstliches Leder\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure lebensechte mechanische Kröte beschwören oder wieder freigeben." }
entries[19794] = { ["name"] = "Zaubermachtschutzbrille Xtrem-Plus", ["text"] = "Wirken in 10 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nZaubermachtschutzbrille Xtrem , Sternrubin (4), Verzaubertes Leder (2), Runenstoff (8)\nZaubermachtschutzbrille Xtrem-Plus\nWird beim Anlegen gebunden\nKopf Stoff\n111 Rüstung\n+23 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst\n(270)" }
