entries[20165] = { ["name"] = "Siegel der Einsicht", ["text"] = "16.4% von Grundmana\nSofort\nErfüllt Euch mit heiligem Licht, das Euer [ Schutz : Nahkampf- und ]Zaubertempo um 10% und Eure gewirkte Heilung um 5% erhöht und Euren Nahkampfangriffen eine Chance gewährt, [ Glyphe 'Schlachtenheiler' : das am schwersten verletzte Gruppen- oder Schlachtzugsmitglied / Euch] um [ Heilige Einsicht : [(0.15 * Angriffskraft + 0.15 * Zaubermacht) * 1.25] / (0.15 * Angriffskraft + 0.15 * Zaubermacht)] [ Heilig : zu heilen und 6% der Grundmanakosten wiederherzustellen, wenn Ihr ein Ziel außerhalb einer Arena oder eines Schlachtfelds trefft ]" }
entries[20167] = { ["name"] = "Siegel der Einsicht", ["text"] = "Sofort\nErfüllt Euch mit heiligem Licht, das Euer [ Schutz : Nahkampf- und ]Zaubertempo um 10% und Eure gewirkte Heilung um 5% erhöht und Euren Nahkampfangriffen eine Chance gewährt, [ Glyphe 'Schlachtenheiler' : das am schwersten verletzte Gruppen- oder Schlachtzugsmitglied / Euch] um [ Heilige Einsicht : [(0.15 * Angriffskraft + 0.15 * Zaubermacht) * 1.25] / (0.15 * Angriffskraft + 0.15 * Zaubermacht)] [ Heilig : zu heilen und 6% der Grundmanakosten wiederherzustellen, wenn Ihr ein Ziel außerhalb einer Arena oder eines Schlachtfelds trefft ]" }
