entries[20217] = { ["name"] = "Segen der Könige", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen, welcher seine Stärke, Beweglichkeit und Intelligenz um 5% erhöht.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten. Spielercharaktere können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
