entries[20243] = { ["name"] = "Verwüsten", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht 220% Waffenschaden plus ( 1 * 220 / 100), zerreißt die Rüstung des Ziels und verursacht den Effekt 'Rüstungsschwächung'.\n\nErsetzt 'Rüstung zerreißen'.\n\nRüstungsschwächung\nSchwächt die Rüstung des Ziels 30 Sek. lang um 4%. Bis zu 3-mal stapelbar." }
