entries[20615] = { ["name"] = "Abfangen", ["text"] = "8 - 25 Meter Reichweite\nSofort\nBenötigt Kampfhaltung\nStürmt auf einen Gegner zu, verursacht 65 Schaden und betäubt ihn 3 Sek. lang." }
entries[20618] = { ["name"] = "Teleportieren", ["text"] = "45 Meter Reichweite\nSofort\nTeleportiert einen Feind mitten in brennende Kohlen." }
entries[20619] = { ["name"] = "Magiereflexion", ["text"] = "35 Meter Reichweite\nSofort 30 sek. Abklingzeit\nLässt alle in der Nähe befindlichen Verbündeten 10 Sek. lang 50% schädliche Zauber reflektieren." }
entries[20620] = { ["name"] = "Aegis des Ragnaros", ["text"] = "Sofort\nUmgibt den Zaubernden mit einem aus Schattenmagie gewobenen Schild. Der Schild hält 5 Min. lang an, absorbiert bis zu 30000 körperlichen oder magischen Schaden und fügt Nahkampfangreifern 250 Schaden zu." }
entries[20623] = { ["name"] = "Feuerschlag", ["text"] = "20 Meter Reichweite\nSofort\nFügt einem Gegner 1080 bis 1320 Feuerschaden zu." }
entries[20626] = { ["name"] = "Muschelsuppe à la Lorenhall", ["text"] = "Wirken in 2 sek.\nReagenzien:\nScharfes Muschelfleisch (2)\n(2)\n35\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 1711 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[20627] = { ["name"] = "Blitzschlagatem", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nLässt 'Blitzschlag' über einen Feind strömen und fügt ihm Naturschaden zu." }
