entries[20657] = { ["name"] = "Säurespucke", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 1 sek.\nFügt einem Gegner Naturschaden zu." }
entries[20663] = { ["name"] = "Schlaf", ["text"] = "90 Mana 30 Meter Reichweite\nSofort\nVersetzt einen Feind bis zu 10 Sek. lang in Schlaf. Jeglicher erlittene Schaden führt dazu, dass das Ziel erwacht. Es kann immer nur jeweils ein Ziel in Schlaf versetzt werden." }
